INSERT INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('phy-energy-friction-001', 'phy', 'กลศาสตร์', 'งานและกฎการอนุรักษ์พลังงานกล', '["แรงและกฎการเคลื่อนที่"]', 'hard', 'ใช้การอนุรักษ์พลังงานร่วมกับงานของแรงเสียดทานในระบบ 2 ช่วง (ระดับค่าย สอวน)', 'mc5', 'วัตถุมวล 2 กิโลกรัม ไถลลงจากพื้นเอียงลื่น (ไม่มีแรงเสียดทาน) สูง 5 เมตร จากหยุดนิ่ง แล้วไถลต่อบนพื้นราบซึ่งมีสัมประสิทธิ์แรงเสียดทาน 0.4 วัตถุจะไถลได้ไกลเท่าใดบนพื้นราบก่อนหยุด (g=10 m/s²)', '["10.0 เมตร", "12.5 เมตร", "15.0 เมตร", "20.0 เมตร", "25.0 เมตร"]', '12.5 เมตร', '["พลังงานศักย์ที่จุดเริ่มต้น = mgh = 2×10×5 = 100 J", "บนพื้นเอียงไม่มีแรงเสียดทาน จึงเป็นพลังงานจลน์ทั้งหมดที่จุดล่างสุด = 100 J", "แรงเสียดทานบนพื้นราบ f = μmg = 0.4×2×10 = 8 N", "ระยะทาง d = พลังงานจลน์ / f = 100/8 = 12.5 เมตร"]', '["คิดว่าพื้นเอียงมีแรงเสียดทานด้วยทั้งที่โจทย์ระบุว่าลื่น", "ลืมว่างานของแรงเสียดทานเท่ากับพลังงานจลน์ที่หายไปทั้งหมด"]');
INSERT INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('phy-circular-001', 'phy', 'กลศาสตร์', 'การเคลื่อนที่แนวโค้ง', '[]', 'hard', 'หาอัตราเร็วต่ำสุดในการเคลื่อนที่เป็นวงกลมแนวดิ่งจากเงื่อนไขแรงตึงเชือกเป็นศูนย์ (ระดับค่าย สอวน)', 'mc5', 'ลูกบอลผูกเชือกยาว 0.9 เมตร แกว่งเป็นวงกลมในระนาบแนวดิ่ง ที่จุดสูงสุดของวงกลม อัตราเร็วต่ำสุดที่ทำให้เชือกยังคงตึงอยู่พอดีเท่ากับกี่เมตรต่อวินาที (g=10 m/s²)', '["2 m/s", "3 m/s", "4 m/s", "5 m/s", "6 m/s"]', '3 m/s', '["ที่จุดสูงสุด เมื่อแรงตึงเชือก T=0 แรงโน้มถ่วงทำหน้าที่เป็นแรงสู่ศูนย์กลางทั้งหมด: mg = mv²/r", "ดังนั้น v_min = √(gr) = √(10×0.9) = √9 = 3 m/s"]', '["ลืมตั้งเงื่อนไข T=0 ที่จุดวิกฤต ไปคำนวณด้วยแรงตึงเชือกที่ไม่ทราบค่าแทน"]');
INSERT INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('phy-circuit-001', 'phy', 'ไฟฟ้า แม่เหล็ก และคลื่นแม่เหล็กไฟฟ้า', 'ไฟฟ้ากระแส', '[]', 'hard', 'ลดวงจรผสมอนุกรม-ขนานแล้วหากำลังไฟฟ้าที่ตัวต้านทานตัวหนึ่ง (ระดับค่าย สอวน)', 'mc5', 'วงจรไฟฟ้าประกอบด้วยตัวต้านทาน R1=2 โอห์ม ต่ออนุกรมกับตัวต้านทาน R2=3 โอห์ม ที่ต่อขนานกับ R3=6 โอห์ม ทั้งหมดต่อกับแหล่งจ่ายไฟฟ้ากระแสตรง 12 โวลต์ (ไม่มีความต้านทานภายใน) กำลังไฟฟ้าที่สูญเสียใน R1 เท่ากับกี่วัตต์', '["8 วัตต์", "12 วัตต์", "18 วัตต์", "24 วัตต์", "36 วัตต์"]', '18 วัตต์', '["ความต้านทานรวมของ R2 กับ R3 ที่ต่อขนาน: (3×6)/(3+6) = 2 โอห์ม", "ความต้านทานรวมทั้งวงจร = R1 + 2 = 2+2 = 4 โอห์ม", "กระแสรวม I = V/R = 12/4 = 3 แอมแปร์ (กระแสนี้ไหลผ่าน R1 ทั้งหมดเพราะต่ออนุกรม)", "กำลังไฟฟ้าใน R1 = I²R1 = 3²×2 = 18 วัตต์"]', '["ลืมว่ากระแสที่ไหลผ่าน R1 คือกระแสรวมทั้งวงจร ไม่ใช่กระแสที่แบ่งไปแต่ละสาขา", "คำนวณความต้านทานขนานผิดโดยใช้สูตรบวกตรงๆ แทนสูตรผกผัน"]');
INSERT INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('phy-momentum-001', 'phy', 'กลศาสตร์', 'โมเมนตัมและการชน', '[]', 'hard', 'หาพลังงานจลน์ที่สูญเสียไปในการชนแบบยึดติดกัน (ระดับค่าย สอวน)', 'mc5', 'รถทดลองมวล 3 กิโลกรัม เคลื่อนที่ด้วยอัตราเร็ว 4 เมตรต่อวินาที เข้าชนรถทดลองมวล 1 กิโลกรัมที่อยู่นิ่ง แล้วทั้งสองติดกันเคลื่อนที่ไปด้วยกัน พลังงานจลน์ที่สูญเสียไปในการชนครั้งนี้เท่ากับกี่จูล', '["3 จูล", "6 จูล", "9 จูล", "12 จูล", "18 จูล"]', '6 จูล', '["ใช้การอนุรักษ์โมเมนตัม: m1v1 = (m1+m2)v'' → 3×4 = 4×v'' → v'' = 3 m/s", "พลังงานจลน์ก่อนชน = ½×3×4² = 24 J", "พลังงานจลน์หลังชน = ½×4×3² = 18 J", "พลังงานที่สูญเสียไป = 24-18 = 6 จูล"]', '["ลืมว่าการชนแบบติดกัน (perfectly inelastic) พลังงานจลน์ไม่อนุรักษ์ ต้องคำนวณก่อน-หลังแยกกัน"]');
INSERT INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('phy-shm-001', 'phy', 'กลศาสตร์', 'การเคลื่อนที่แบบฮาร์มอนิกส์อย่างง่าย', '[]', 'hard', 'หาอัตราเร็วสูงสุดของ SHM ด้วยวิธีการอนุรักษ์พลังงาน (ระดับค่าย สอวน)', 'mc5', 'วัตถุมวล 0.5 กิโลกรัม ติดกับสปริงที่มีค่าคงตัวสปริง 200 นิวตันต่อเมตร ดึงให้เคลื่อนที่ออกจากตำแหน่งสมดุล 0.1 เมตร แล้วปล่อยจากหยุดนิ่ง อัตราเร็วสูงสุดของวัตถุขณะเคลื่อนที่ผ่านตำแหน่งสมดุลเท่ากับกี่เมตรต่อวินาที', '["0.5 m/s", "1.0 m/s", "1.5 m/s", "2.0 m/s", "2.5 m/s"]', '2.0 m/s', '["ใช้การอนุรักษ์พลังงาน: ½kA² = ½mv_max²", "v_max = A√(k/m) = 0.1×√(200/0.5) = 0.1×√400 = 0.1×20 = 2.0 m/s"]', '["ลืมถอดรากที่สองของ k/m ก่อนคูณด้วยแอมพลิจูด"]');
INSERT INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('phy-doppler-001', 'phy', 'คลื่นกล และแสง', 'เสียง', '[]', 'hard', 'ใช้สมการดอปเพลอร์กรณีแหล่งกำเนิดเคลื่อนที่เข้าหาผู้สังเกตที่หยุดนิ่ง (ระดับค่าย สอวน)', 'mc5', 'แหล่งกำเนิดเสียงความถี่ 640 เฮิรตซ์ เคลื่อนที่เข้าหาผู้สังเกตที่หยุดนิ่ง ด้วยอัตราเร็ว 20 เมตรต่อวินาที ถ้าอัตราเร็วเสียงในอากาศเท่ากับ 340 เมตรต่อวินาที ผู้สังเกตจะได้ยินเสียงความถี่เท่าใด', '["600 Hz", "640 Hz", "660 Hz", "680 Hz", "700 Hz"]', '680 Hz', '["สมการดอปเพลอร์เมื่อแหล่งกำเนิดเคลื่อนที่เข้าหาผู้สังเกตที่หยุดนิ่ง: f'' = f×v/(v-vs)", "f'' = 640×340/(340-20) = 640×340/320 = 680 Hz"]', '["ใส่เครื่องหมายผิด ใช้ (v+vs) แทน (v-vs) สำหรับกรณีแหล่งกำเนิดเคลื่อนที่เข้าหา"]');
